from pathlib import Path
import subprocess,csv,re,json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'audit'

def baseline(name):
    return subprocess.check_output(['git','show',f'baseline:src/{name}'],cwd=ROOT,text=True).splitlines()

