out=['# Реєстр дефектів проєктування: СР №2, варіант 20','','Джерело: **не змінений** код архіву V20-SportEvents.zip, тег `baseline`. Діапазони рядків — базова версія. Всі нижче наведені цитати з реальних файлів. Тяжкість 1–5; частота 1–4; пріоритет = тяжкість × частота. Вплив та оцінки часу є інженерною оцінкою, не інструментальним виміром.','', '|ID|Файл:рядки|Каталог дефекту|Серйозність|Частота|Пріоритет|','|---|---|---|---:|---:|---:|']
for ID,file,start,end,kind,severity,frequency,*_ in items:
    out.append(f'|{ID}|`{file}:{start}–{end}`|{kind}|{severity}|{frequency}|{severity*frequency}|')
for ID,file,start,end,kind,sev,freq,ben,risk,mins,impact,proof,fix in items:
    raw=baseline(file)
    span=raw[start-1:min(end,start+10,len(raw))]
    out += ['',f'## {ID}: {kind}',f'**Місце:** `{file}:{start}–{end}`. **Тяжкість:** {sev}/5, **частота:** {freq}, **пріоритет:** {sev*freq}.',f'**Доказ і вплив:** {proof} Категорія: {impact}.', f'**Гіпотеза:** {fix}. **Вигода:** {ben}/5, **ризик зміни поведінки:** {risk}/5, **планова трудомісткість:** {mins} хв.','','```csharp']
    out.extend(f'{start+i:>3}: {line}' for i,line in enumerate(span))
    out+=['```']
(OUT/'defects.md').write_text('\n'.join(out)+'\n',encoding='utf-8')

schedule=sorted(items,key=lambda x:(-(x[7]/x[8]),x[9]))
plan=['# План змін за вигодою/ризиком','','У таблиці оцінки часу **планові**, не фактичний хронометраж. Перед кожним кроком має бути успішна збірка та тест; у середовищі генерації SDK відсутній, тому ці гейти фактично не виконано.','', '|Черга|ID|Дія|Вигода|Ризик|Хв|Індекс В/Р|','|---:|---|---|---:|---:|---:|---:|']
for ix,item in enumerate(schedule,1):
    ID, file,start,end,kind,sev,freq,ben,risk,mins,impact,proof,fix=item
    plan.append(f'|{ix}|{ID}|{fix}|{ben}|{risk}|{mins}|{ben/risk:.2f}|')
plan+=['', '## Правила безпеки','','1. Один тип рефакторингу — окремий коміт; не змішувати з виправленнями функціональних помилок.','2. Непокритий ризиковий крок не вважати завершеним без тестів.','3. Після кожного кроку обов’язково виконати `dotnet build` і `dotnet test` на Windows; якщо тест падає — повернутись до попереднього коміту.','4. Не міняти очікування характеризаційних тестів заради зеленого результату.','5. Зафіксувати невирішені ризики в реєстрі боргу.']
(OUT/'plan.md').write_text('\n'.join(plan)+'\n',encoding='utf-8')

inventory=['# Інвентаризація вихідного рішення','','Джерело: `V20-SportEvents.zip`, тег baseline. Логічні LOC, CC, fan-out і клони обчислено скриптом `scripts/measure.py` (лексична, **не Roslyn** методика).','', '|Файл|Типи|Фізичні рядки|Опис|','|---|---|---:|---|']
desc={'EventLog.cs':'Журнал подій у тимчасовій теці','Match.cs':'Модель матчу і статусів','MatchService.cs':'Календар, результати й зміни статусів','Participant.cs':'Дані команди','Program.cs':'Сценарій запуску та тестові матчі','ReportPrinter.cs':'Друк таблиці й подіуму','ResultTable.cs':'Рейтинг, сортування та присвоєння місць','TournamentRepository.cs':'Сховище, імпорт, пошук і друк'}
for file in sorted(desc):
    raw=baseline(file)
    classes=re.findall(r'\b(?:class|enum)\s+(\w+)', '\n'.join(raw))
    inventory.append(f'|`src/{file}`|{", ".join(classes)}|{len(raw)}|{desc[file]}|')
summary=json.loads((OUT/'summary-before.json').read_text(encoding='utf-8'))
inventory+=['',f'Усього: **{summary["files"]}** C# файлів; **{summary["physical_lines"]}** фізичних рядків; **{summary["nonblank_noncomment_lines"]}** непорожніх рядків без рядків-коментарів; **{summary["methods_measured"]}** виміряних методів/конструкторів.','', 'Окремо: фізичний LOC у таблиці інвентаря включає порожні рядки й коментарі, тоді як метрики методів виключають їх, а також рядки з одними дужками.']
(OUT/'inventory.md').write_text('\n'.join(inventory)+'\n',encoding='utf-8')

refactor_commits=[]
for line in subprocess.check_output(['git','log','--reverse','--format=%h|%s','after-refactoring','--'],cwd=ROOT,text=True).splitlines():
    sha,subject=line.split('|',1)
    if subject.startswith('refactor('):
        code=re.search(r'R\d+[a-z]?',subject)
        refactor_commits.append((sha,code.group(0) if code else '',subject))

notes=['# Журнал рішень СР №2','','**Важливо:** це документ інженерних рішень, ухвалених під час підготовки коду з допомогою ШІ. Він не є доказом, що .NET-збірка або xUnit-тести пройшли. Перевірки потрібно виконати на ПК з SDK, дописати їх реальні логи й лише після цього відправляти на оцінювання.','', '## Вихідні рішення','', '- Не використовувати власний семестровий SportEvents як донора: аудит здійснюється над окремим присланим архівом `V20-SportEvents.zip`.','- Не виправляти неочевидні помилки в логіці DNF, рахунку, імпорту або обробки винятків під виглядом рефакторингу.','- Характеризаційні тести фіксують поточний порядок команд, нічиї та присвоєння місць.','- Публічні поля `RankCalls`, `Notes` інкапсульовано; це джерельно несумісно для клієнтів, які **присвоювали** їм інші значення, тому потрібно підтвердити відсутність такого використання на всіх клієнтах.','- У послідовності кроків немає підміни історичних дат Git.','', '## Коміти рефакторингу (справжні локальні SHA)','','|Крок|Код|Коміт|Зміна|','|---:|---|---|---|']
for i,(sha,code,subject) in enumerate(refactor_commits,1):notes.append(f'|{i}|{code}|`{sha}`|{subject}|')
notes += ['','## Ризики і межі доказу','','- Відсутній .NET SDK у середовищі генерації: тестові очікування складено за аналізом вихідного коду, але запуск не підтверджено.','- `DateTime.Today < 2024-08-01` неможливо чесно охарактеризувати на поточній даті без шва часу. Поведінку збережено.','- Після переміщення коду в `RankingRowMapper` та `TableStatsFormatter` потрібно перевірити друк stdout до/після byte-for-byte: звіт про цю перевірку не генерувати без запуску.','- Офіційні Roslyn CC можуть не збігтися з лексичним рахунком; методика й обмеження вказані у звіті.']
(OUT/'decisions.md').write_text('\n'.join(notes)+'\n',encoding='utf-8')

