tech=['# Реєстр технічного боргу та план погашення','','PERT-оцінка: `(оптимістична + 4 × найбільш імовірна + песимістична)/6`. **Усі години — прогноз**, а не витрачений час. Вартість обслуговування — умовна оцінка годин на місяць.','','|ID|Проблема|Квадрант / строк|O|M|P|Очік. год|Обсл., год/міс|Окупність, міс|Термін|Критерій закриття|','|---|---|---|---:|---:|---:|---:|---:|---:|---|---|']
total_body=total_maint=0
for ID,problem,kind,duration,o,m,p,maint,when,criterion in debt:
    body=(o+4*m+p)/6
    total_body+=body;total_maint+=maint
    tech.append(f'|{ID}|{problem}|{kind}; {duration}|{o}|{m}|{p}|{body:.2f}|{maint:.1f}|{body/maint:.1f}|{when}|{criterion}|')
tech+=['',f'**Тіло всього:** {total_body:.2f} год; **обслуговування:** {total_maint:.1f} год/міс; **умовний строк окупності всього пакета:** {total_body/total_maint:.2f} міс.','', 'План пріоритету: спочатку TD-07 (докази), TD-05 (час), TD-02 (цілісність імпорту), TD-01 (журнал), далі TD-06, TD-04, TD-03. Оцінки не означають виконання цих змін.']
(OUT/'technical-debt.md').write_text('\n'.join(tech)+'\n',encoding='utf-8')
print('Audit docs: defects',len(items),'catalog types',len(set(x[4] for x in items)),'distinct refactor codes',len({re.match(r'R\d+',x[1]).group() for x in refactor_commits}))
print('Debt',len(debt),'hours',round(total_body,2))
